    main.insertAdjacentHTML('beforeend','<section><div class="wrap grid three"><article class="card"><p class="eyebrow">01 / CONTROL</p><h2>One workflow. More control.</h2><p>Create client access, manage credits and keep your operation organised from one professional reseller offer.</p></article><article class="card"><p class="eyebrow">02 / GROW</p><h2>Built for your brand.</h2><p>Use API access, white-label options and an own custom domain as your customer base grows.</p></article><article class="card"><p class="eyebrow">03 / SUPPORT</p><h2>Support that stays close.</h2><p>Get 24/7 support for activation, setup and practical customer questions.</p></article></div></section><section><div class="wrap"><div class="head"><p class="eyebrow">RESELLER FAQ</p><h2>Everything you need to start with confidence.</h2></div><div class="grid three"><article class="card"><h3>How do credits work?</h3><p>0.1 credit activates one month, 0.3 covers three months, 0.5 covers six months and one credit covers twelve months.</p></article><article class="card"><h3>Can I use my own domain?</h3><p>Yes. Ask sales about white-label and custom-domain options for your package.</p></article><article class="card"><h3>Can I request a larger package?</h3><p>Yes. Contact sales through WhatsApp for 20, 50, 100 credits or a tailored Grow package.</p></article></div></div></section>');
