    const pricingPanel='<section><div class="wrap split"><div><div class="eyebrow">Tivione subscription experience</div><h2>One subscription. Everything you need to watch.</h2><p>Choose the Tivione duration that suits you, then use your preferred compatible player. Every plan is built around stable delivery, global EPG and straightforward help when you need it.</p><a class="button" href="https://t.me/premiumiptvpanelscom" target="_blank" rel="noopener noreferrer">Ask on Telegram ↗</a></div><div class="grid"><article class="card"><h3>Instant activation</h3><p>Once your order is confirmed, the team prepares your access and helps you start on the right player.</p></article><article class="card"><h3>Players for your devices</h3><p>Use compatible apps on Smart TV, Fire TV, Android, mobile or desktop with clear setup guidance.</p></article><article class="card"><h3>Support when you need it</h3><p>Contact the Tivione team for plan questions, player setup and account assistance.</p></article></div></div></section>';
    const resellerPanel='<section><div class="wrap split"><div><div class="eyebrow">Tivione reseller workflow</div><h2>One workflow. More control with Tivione.</h2><p>Build and manage your Tivione reseller activity with flexible credits, reliable server access and practical assistance from the team. Package features are confirmed before activation for your account level.</p><a class="button" href="https://t.me/premiumiptvpanelscom" target="_blank" rel="noopener noreferrer">Activate with Telegram ↗</a></div><div class="grid"><article class="card"><h3>Sub-reseller creation</h3><p>Ask which Tivione packages allow sub-reseller accounts and credit allocation for your team.</p></article><article class="card"><h3>Xtream Codes / MAG / M3U management</h3><p>Confirm the supported connection formats and device compatibility available for your Tivione package.</p></article><article class="card"><h3>24/7 Tivione support</h3><p>Send a support request at any time for activation, account questions or practical setup help.</p></article></div></div></section>';
